  <script>
    var currentTheme = 'light';
    function toggleMenu() { document.getElementById('vizMenuDropdown').classList.toggle('open'); }
    function cycleTheme() { currentTheme = currentTheme === 'light' ? 'dark' : 'light'; document.documentElement.className = 'theme-' + currentTheme; onThemeChange(); }
    async function downloadImage() {}

    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') return null;
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var ctx = document.getElementById(canvasId);
          if (!ctx) return null;
          var chart = new Chart(ctx, config);
          this.charts.set(canvasId, chart);
          return chart;
        } catch (e) { return null; }
      }
    };

    function buildCharts() {
      if (typeof Chart === 'undefined') return;
      Chart.defaults.font.family = 'Inter';

      var thresholdPlugin = {
        id: 'horizontalLine',
        beforeDraw: function(chart) {
          var ctx = chart.ctx;
          var yAxis = chart.scales.y;
          var xAxis = chart.scales.x;
          var yPos = yAxis.getPixelForValue(60);
          ctx.save();
          ctx.beginPath();
          ctx.moveTo(xAxis.left, yPos);
          ctx.lineTo(xAxis.right, yPos);
          ctx.lineWidth = 4;
          ctx.strokeStyle = '#BE123C';
          ctx.setLineDash([10, 10]);
          ctx.stroke();
          ctx.restore();
        }
      };

      ChartManager.safeInit('performanceChart', {
        type: 'bar',
        data: {
          labels: ['GPT-4\n(USMLE)', 'Med-PaLM 2\n(MedQA)', 'GPT-3.5\n(USMLE)'],
          datasets: [{
            label: 'Benchmark Score (%)',
            data: [92, 86.5, 60],
            backgroundColor: ['#0F3A64', '#1E40AF', '#94A3B8'],
            borderRadius: 12,
            borderWidth: 0,
            barThickness: 80
          }]
        },
        plugins: [thresholdPlugin],
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            tooltip: { enabled: true, titleFont: { size: 28 }, bodyFont: { size: 32, weight: 'bold' }, padding: 24, cornerRadius: 16 }
          },
          scales: {
            y: {
              beginAtZero: true, max: 100,
              ticks: { font: { size: 28, weight: '600' }, color: '#475569', callback: function(v) { return v + '%'; }, padding: 20 },
              grid: { color: '#E2E8F0', drawBorder: false, lineWidth: 2 }
            },
            x: {
              ticks: { font: { size: 28, weight: '700' }, color: '#0F172A', padding: 20 },
              grid: { display: false, drawBorder: false }
            }
          },
          layout: { padding: { top: 30, right: 30, bottom: 0, left: 0 } }
        }
      });
    }

    function onThemeChange() { buildCharts(); }
    document.addEventListener('DOMContentLoaded', buildCharts);
  </script>
